def find_blocks(g):
    h,w=len(g),len(g[0]); seen=set(); out=[]
    for i in range(h):
        for j in range(w):
            if g[i][j] and (i,j) not in seen:
                c=g[i][j]; s=[(i,j)]; comp=set(); q=[(i,j)]
                while q:
                    y,x=q.pop()
                    if (y,x) in comp: continue
                    comp.add((y,x))
                    for dy in(-1,0,1):
                        for dx in(-1,0,1):
                            ny,nx=y+dy,x+dx
                            if 0<=ny<h and 0<=nx<w and g[ny][nx]==c and (ny,nx) not in comp: q.append((ny,nx))
                seen|=comp
                if len(comp)>=4: out.append((c,comp))
    return out

def transform(g):
    h,w=len(g),len(g[0])
    out=[row[:] for row in g]
    lines=[]
    for c,comp in find_blocks(g):
        rs={y for y,x in comp}; cs={x for y,x in comp}
        r0=(min(rs)+max(rs))//2; c0=(min(cs)+max(cs))//2
        lines.append((c,'r',r0)); lines.append((c,'c',c0))
    for i in range(h):
        for j in range(w):
            hits=[ln for ln in lines if (ln[1]=='r' and ln[2]==i) or (ln[1]=='c' and ln[2]==j)]
            if hits:
                cols={ln[0] for ln in hits}
                out[i][j]= next(iter(cols)) if len(cols)==1 else 0
    return out

